// Daily Wrap — headlines, yesterday's scores, today's games.
// No API keys required: headlines come from headlines.json, generated by a
// scheduled GitHub Actions workflow (scripts/fetch-headlines.js) that fetches
// public RSS feeds server-side, where CORS doesn't apply. Sports data comes
// from ESPN's public scoreboard API, fetched directly from the browser.

// Fallback only — see fetchWithFallback, which tries the URL directly first
// and only reaches for these if that fails. ESPN allows cross-origin
// requests, so its scoreboard calls succeed direct and rarely need these.
const CORS_PROXIES = [
  (url) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
  (url) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
  // corsproxy.io removed: returned 403 on every single request (confirmed in
  // a browser console log, 2026-07-29) — a guaranteed-failing branch.
];

// Grouped by sport so the site stays organized even on days when only one
// sport has games (e.g. baseball-only stretches of the calendar). Covers the
// leagues with the heaviest US betting volume; a category with no games that
// day auto-collapses (see renderLeagueGroups) rather than disappearing.
// `siteSport` is the espn.com URL segment used to link team/fighter names to
// their real ESPN page (stats, roster, full schedule) instead of building a
// second copy of that here.
const LEAGUES = [
  { id: 'nfl', name: 'NFL', path: 'football/nfl', group: 'Football', siteSport: 'nfl' },
  { id: 'ncaaf', name: 'College Football', path: 'football/college-football', group: 'Football', siteSport: 'college-football' },
  { id: 'nba', name: 'NBA', path: 'basketball/nba', group: 'Basketball', siteSport: 'nba' },
  { id: 'wnba', name: 'WNBA', path: 'basketball/wnba', group: 'Basketball', siteSport: 'wnba' },
  { id: 'ncaab', name: 'College Basketball', path: 'basketball/mens-college-basketball', group: 'Basketball', siteSport: 'mens-college-basketball' },
  { id: 'mlb', name: 'MLB', path: 'baseball/mlb', group: 'Baseball', siteSport: 'mlb' },
  { id: 'nhl', name: 'NHL', path: 'hockey/nhl', group: 'Hockey', siteSport: 'nhl' },
  { id: 'epl', name: 'Premier League', path: 'soccer/eng.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'ucl', name: 'Champions League', path: 'soccer/uefa.champions', group: 'Soccer', siteSport: 'soccer' },
  { id: 'uel', name: 'Europa League', path: 'soccer/uefa.europa', group: 'Soccer', siteSport: 'soccer' },
  { id: 'laliga', name: 'La Liga', path: 'soccer/esp.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'seriea', name: 'Serie A', path: 'soccer/ita.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'bundesliga', name: 'Bundesliga', path: 'soccer/ger.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'ligue1', name: 'Ligue 1', path: 'soccer/fra.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'mls', name: 'MLS', path: 'soccer/usa.1', group: 'Soccer', siteSport: 'soccer' },
  { id: 'ufc', name: 'UFC', path: 'mma/ufc', group: 'Combat Sports', siteSport: 'mma' },
  // Boxing removed: ESPN returns a genuine HTTP 400 for the 'boxing/boxing'
  // path (direct, not via a proxy — confirmed in a browser console log), so
  // it only ever produced errors. No verified correct path to swap in.
];

const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(today.getDate() - 1);
const tomorrow = new Date(today);
tomorrow.setDate(today.getDate() + 1);

function pad(n) { return String(n).padStart(2, '0'); }
function toYYYYMMDD(d) { return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`; }
function longDate(d) { return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }); }

// A direct attempt either succeeds quickly or fails fast on CORS, so it gets
// a short leash; the free proxies are slower and get a longer one.
const DIRECT_TIMEOUT_MS = 6000;
const PROXY_TIMEOUT_MS = 20000;

async function fetchWithTimeout(url, timeoutMs = DIRECT_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res;
  } finally {
    clearTimeout(timer);
  }
}

async function fetchWithFallback(url) {
  // Direct first, on its own — ESPN allows cross-origin requests, so this
  // succeeds for essentially every call and the proxies below go unused.
  try {
    const res = await fetchWithTimeout(url);
    return await res.json();
  } catch {
    // Fall through to the proxies for the rare direct failure.
  }

  const attempts = CORS_PROXIES.map((makeProxyUrl) =>
    fetchWithTimeout(makeProxyUrl(url), PROXY_TIMEOUT_MS).then((res) => res.json())
  );
  try {
    return await Promise.any(attempts);
  } catch (aggregateErr) {
    throw aggregateErr.errors?.[0] || aggregateErr;
  }
}

// ---------- Headlines ----------

function relativeTime(ts) {
  const mins = Math.round((Date.now() - ts) / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins} min ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours} hr ago`;
  const days = Math.round(hours / 24);
  return `${days} day${days === 1 ? '' : 's'} ago`;
}

function escapeAttr(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function renderSourceBody(source) {
  const items = source.items || [];
  if (items.length === 0) return '<p class="empty">Couldn\'t load.</p>';
  const staleNote = !source.ok && source.updatedAt
    ? `<p class="empty">Saved copy from ${relativeTime(new Date(source.updatedAt).getTime())} — couldn't refresh just now.</p>`
    : '';
  const modelName = getAiModelName();
  return staleNote + '<ul class="headline-list">' + items.map((it) => {
    const titleAttr = escapeAttr(it.title);
    const sourceAttr = escapeAttr(source.name);
    const linkAttr = escapeAttr(it.link);
    return `<li class="headline-item">
      <a href="${it.link}" target="_blank" rel="noopener noreferrer" class="headline-link">${escapeHtml(it.title)}</a>
      <button class="ask-gemini-btn" data-title="${titleAttr}" data-source="${sourceAttr}" data-link="${linkAttr}" title="Ask ${modelName} about this headline">
        <span class="sparkle-icon">✨</span> Ask ${modelName}
      </button>
    </li>`;
  }).join('') + '</ul>';
}

async function loadHeadlines() {
  const container = document.getElementById('headlines-list');
  const sub = document.getElementById('headlines-sub');
  sub.textContent = longDate(today);
  container.innerHTML = '<p class="loading">Loading headlines…</p>';

  let data;
  try {
    const res = await fetch('headlines.json', { cache: 'no-store' });
    const contentType = res.headers.get('content-type') || '';
    if (!res.ok || contentType.includes('text/html')) {
      throw new Error(`Invalid response for headlines.json: status ${res.status}, type ${contentType}`);
    }
    data = await res.json();
  } catch (err) {
    console.warn('headlines.json not directly available, attempting refresh API:', err);
    try {
      const refreshRes = await fetch('/api/refresh-headlines', { method: 'POST' });
      if (refreshRes.ok) {
        data = await refreshRes.json();
        if (data.message && !data.sources) {
          const res2 = await fetch('headlines.json', { cache: 'no-store' });
          data = await res2.json();
        }
      }
    } catch (refreshErr) {
      console.warn('Failed to refresh headlines via API:', refreshErr);
    }
  }

  if (!data || !data.sources || data.sources.length === 0) {
    container.innerHTML = '<p class="error">Couldn\'t load headlines right now. Try refreshing the page.</p>';
    return;
  }

  container.innerHTML = '';
  for (const source of data.sources || []) {
    const el = document.createElement('details');
    el.className = 'source-group';
    if ((source.items || []).length > 0) el.open = true;
    el.innerHTML = `<summary><h3>${source.name}</h3></summary>` +
      `<div class="source-group-body">${renderSourceBody(source)}</div>`;
    container.appendChild(el);
  }
}

// ---------- Sports ----------

// A competitor is either a team (most sports) or an athlete (fights). Either
// way, link its name to the real ESPN page for that team/fighter — building
// and keeping our own stats/roster pages in sync would be its own project.
function extractParticipant(c, league) {
  const isAthlete = !!c.athlete && !c.team;
  const entity = c.team || c.athlete;
  const name = entity?.displayName || entity?.shortDisplayName || entity?.name || 'TBD';
  const shortName = entity?.abbreviation || entity?.shortDisplayName || entity?.name || name;
  const link = entity?.id
    ? `https://www.espn.com/${league.siteSport}/${isAthlete ? 'player' : 'team'}/_/id/${entity.id}`
    : null;
  const rank = c.curatedRank?.current && c.curatedRank.current <= 25 ? c.curatedRank.current : null;
  return { name, shortName, score: c.score, link, rank };
}

function formatML(val) {
  if (!val || val === 'OFF') return val;
  const num = parseInt(val, 10);
  if (!isNaN(num) && num > 0) return `+${num}`;
  return `${val}`;
}

function parseOdds(comp, eventSummary = null) {
  const oddsArr = comp?.odds || [];
  const primaryOdds = oddsArr[0] || eventSummary?.pickcenter?.[0] || null;
  if (!primaryOdds && !eventSummary?.winprobability) return null;

  const providerName = primaryOdds?.provider?.displayName || 'DraftKings';
  let providerLink = primaryOdds?.link?.href || null;
  if (!providerLink && Array.isArray(primaryOdds?.links)) {
    const gameLink = primaryOdds.links.find(l => l.rel?.includes('game') || l.rel?.includes('main') || l.rel?.includes('desktop'));
    if (gameLink) providerLink = gameLink.href;
  }

  const details = primaryOdds?.details || '';
  const overUnder = primaryOdds?.overUnder ? `O/U ${primaryOdds.overUnder}` : '';
  const spread = primaryOdds?.spread ? (primaryOdds.spread > 0 ? `+${primaryOdds.spread}` : `${primaryOdds.spread}`) : '';

  const ml = primaryOdds?.moneyline || {};
  const openHomeML = ml.home?.open?.odds;
  const openAwayML = ml.away?.open?.odds;

  const homeTeamOddsML = primaryOdds?.homeTeamOdds?.moneyLine !== undefined ? String(primaryOdds.homeTeamOdds.moneyLine) : null;
  const awayTeamOddsML = primaryOdds?.awayTeamOdds?.moneyLine !== undefined ? String(primaryOdds.awayTeamOdds.moneyLine) : null;

  const closeHomeML = ml.home?.close?.odds || ml.home?.open?.odds || homeTeamOddsML;
  const closeAwayML = ml.away?.close?.odds || ml.away?.open?.odds || awayTeamOddsML;
  const closeDrawML = ml.draw?.close?.odds || ml.draw?.open?.odds;

  const liveHomeML = ml.home?.live?.odds;
  const liveAwayML = ml.away?.live?.odds;
  const liveDrawML = ml.draw?.live?.odds;

  const ps = primaryOdds?.pointSpread || {};
  const homeSpreadLine = ps.home?.close?.line || ps.home?.open?.line;
  const homeSpreadOdds = ps.home?.close?.odds || ps.home?.open?.odds;
  const awaySpreadLine = ps.away?.close?.line || ps.away?.open?.line;
  const awaySpreadOdds = ps.away?.close?.odds || ps.away?.open?.odds;

  let winProb = null;
  if (eventSummary?.winprobability && eventSummary.winprobability.length > 0) {
    const lastWp = eventSummary.winprobability[eventSummary.winprobability.length - 1];
    if (typeof lastWp.homeWinPercentage === 'number') {
      winProb = Math.round(lastWp.homeWinPercentage * 100);
    }
  }

  return {
    providerName,
    providerLink,
    details,
    overUnder,
    spread,
    openHomeML,
    openAwayML,
    closeHomeML,
    closeAwayML,
    closeDrawML,
    liveHomeML,
    liveAwayML,
    liveDrawML,
    homeSpread: homeSpreadLine ? `${homeSpreadLine}${homeSpreadOdds ? ` (${formatML(homeSpreadOdds)})` : ''}` : '',
    awaySpread: awaySpreadLine ? `${awaySpreadLine}${awaySpreadOdds ? ` (${formatML(awaySpreadOdds)})` : ''}` : '',
    winProb,
  };
}

function normalizeEvent(ev, league, eventSummary = null) {
  const comp = ev.competitions?.[0];
  const statusType = comp?.status?.type || {};
  const competitors = comp?.competitors || [];
  const home = competitors.find((c) => c.homeAway === 'home') || competitors[0];
  const away = competitors.find((c) => c.homeAway === 'away') || competitors[1];
  return {
    date: ev.date,
    state: statusType.state, // 'pre' | 'in' | 'post'
    completed: !!statusType.completed,
    statusDetail: statusType.shortDetail || statusType.detail || '',
    home: home ? extractParticipant(home, league) : null,
    away: away ? extractParticipant(away, league) : null,
    odds: parseOdds(comp, eventSummary),
  };
}

async function fetchScoreboard(league, date) {
  const url = `https://site.api.espn.com/apis/site/v2/sports/${league.path}/scoreboard?dates=${toYYYYMMDD(date)}`;
  try {
    const data = await fetchWithFallback(url);
    const rawEvents = data.events || [];
    
    // Fetch summary for live games ('in'), completed games ('post'), or events lacking direct odds
    const normalized = await Promise.all(
      rawEvents.map(async (ev) => {
        const comp = ev.competitions?.[0];
        const state = comp?.status?.type?.state;
        let summary = null;
        if (state === 'in' || state === 'post' || !comp?.odds?.length) {
          try {
            summary = await fetchWithFallback(
              `https://site.api.espn.com/apis/site/v2/sports/${league.path}/summary?event=${ev.id}`
            );
          } catch {
            // Fall back to scoreboard-level data if summary fetch fails
          }
        }
        return normalizeEvent(ev, league, summary);
      })
    );
    return normalized;
  } catch (err) {
    console.warn(`Scoreboard fetch failed for ${league.name}:`, err);
    return null; // signals a failed fetch, distinct from "no games"
  }
}

function groupBy(list, keyFn) {
  const map = new Map();
  for (const item of list) {
    const key = keyFn(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  }
  return map;
}

function extractMoneylineValues(odds) {
  let homeML = null;
  let awayML = null;

  if (odds?.closeHomeML !== null && odds?.closeHomeML !== undefined &&
      odds?.closeAwayML !== null && odds?.closeAwayML !== undefined) {
    const h = parseInt(odds.closeHomeML, 10);
    const a = parseInt(odds.closeAwayML, 10);
    if (!isNaN(h) && !isNaN(a)) {
      homeML = h;
      awayML = a;
    }
  }

  if ((homeML === null || awayML === null) && odds?.details) {
    // Extract moneyline patterns like CHC -111 / STL -109 or LAD -115, SD +105
    const mlMatches = odds.details.match(/[-+]?\d{3,4}/g);
    if (mlMatches && mlMatches.length >= 2) {
      const h = parseInt(mlMatches[0], 10);
      const a = parseInt(mlMatches[1], 10);
      if (!isNaN(h) && !isNaN(a)) {
        homeML = h;
        awayML = a;
      }
    }
  }

  return { homeML, awayML };
}

function calcMLDifference(homeML, awayML) {
  if (homeML === null || awayML === null || isNaN(homeML) || isNaN(awayML)) return null;
  if (homeML <= 0 && awayML <= 0) {
    return Math.abs(homeML - awayML);
  }
  if (homeML >= 0 && awayML >= 0) {
    return Math.abs(homeML - awayML);
  }
  const d1 = Math.abs(Math.abs(homeML) - 100);
  const d2 = Math.abs(Math.abs(awayML) - 100);
  return d1 + d2;
}

function calculateExcitement(ev, league) {
  let score = 30; // base score
  let reasons = [];

  const home = ev?.home;
  const away = ev?.away;
  const odds = ev?.odds;

  // Identify sport
  const isMLB = ['mlb', 'baseball'].some(s => league?.path?.includes(s) || league?.siteSport === 'baseball');

  // Determine game status accurately:
  // state can be 'pre' (unstarted), 'in' (live), or 'post' (completed)
  const isPreGame = ev?.state === 'pre' || (!ev?.completed && ev?.state !== 'in');
  const isLive = ev?.state === 'in' && !ev?.completed;
  const isCompleted = ev?.completed || ev?.state === 'post';

  // 1. Check Rankings / Top Teams (Applies to all games)
  const homeRank = home?.rank;
  const awayRank = away?.rank;
  if (homeRank && awayRank) {
    score += 35;
    reasons.push(`Ranked matchup (#${awayRank} vs #${homeRank})`);
  } else if (homeRank || awayRank) {
    score += 18;
    reasons.push(`Top 25 team (#${homeRank || awayRank})`);
  }

  // 2. Check Line / Spread / Moneyline (Crucial for Pre-game and Live evaluation)
  if (odds) {
    // A. Spread check (Skip if MLB because run lines are almost always -1.5/+1.5)
    if (!isMLB && odds.details) {
      let spreadVal = null;
      const detailsUpper = odds.details.toUpperCase();
      if (detailsUpper.includes('EVEN') || detailsUpper.includes('PK') || detailsUpper.includes('PICK')) {
        spreadVal = 0;
      } else {
        const match = odds.details.match(/[-+]?\d+(\.\d+)?/);
        if (match) {
          spreadVal = Math.abs(parseFloat(match[0]));
        }
      }

      if (spreadVal !== null && !isNaN(spreadVal)) {
        if (spreadVal <= 1.5) {
          score += 38;
          reasons.push(`Ultra-tight spread (${odds.details})`);
        } else if (spreadVal <= 3.5) {
          score += 30;
          reasons.push(`Tight spread (${odds.details})`);
        } else if (spreadVal <= 6.5) {
          score += 15;
          reasons.push(`Close line (${odds.details})`);
        } else if (spreadVal >= 14) {
          score -= 20; // Blowout line
        }
      }
    }

    // B. Moneyline Close Check (Parses direct ML fields or strings like CHC -111 / STL -109)
    const { homeML, awayML } = extractMoneylineValues(odds);
    const mlDiff = calcMLDifference(homeML, awayML);

    if (mlDiff !== null) {
      if (mlDiff <= 30) {
        score += 38;
        const hStr = homeML > 0 ? `+${homeML}` : `${homeML}`;
        const aStr = awayML > 0 ? `+${awayML}` : `${awayML}`;
        reasons.push(`Tight moneyline (${aStr} / ${hStr})`);
      } else if (mlDiff <= 60) {
        score += 25;
        if (!reasons.some(r => r.includes('spread'))) {
          const hStr = homeML > 0 ? `+${homeML}` : `${homeML}`;
          const aStr = awayML > 0 ? `+${awayML}` : `${awayML}`;
          reasons.push(`Close moneyline (${aStr} / ${hStr})`);
        }
      } else if (mlDiff >= 150) {
        score -= 15;
      }
    }

    // C. Win probability
    if (odds.winProb !== null && odds.winProb !== undefined) {
      const probDiff = Math.abs(odds.winProb - 50);
      if (probDiff <= 8) { // 42% - 58%
        score += 22;
        reasons.push(`50/50 win probability (${odds.winProb}%)`);
      }
    }
  }

  // 3. Score Differential Logic: Strictly for LIVE or COMPLETED games.
  // Pre-game / unstarted games completely skip score differential checks so 0-0 ties are ignored!
  if (!isPreGame && (isLive || isCompleted)) {
    if (home && away && home.score !== undefined && away.score !== undefined && home.score !== '' && away.score !== '') {
      const s1 = parseInt(home.score, 10);
      const s2 = parseInt(away.score, 10);
      if (!isNaN(s1) && !isNaN(s2)) {
        const diff = Math.abs(s1 - s2);
        const isLowScoreSport = ['mlb', 'nhl', 'soccer', 'epl', 'usa.1', 'esp.1'].some(s => league?.path?.includes(s));

        if (isLive) {
          // LIVE IN-PROGRESS GAME LOGIC
          if (isLowScoreSport) {
            if (diff === 0) {
              score += 35;
              reasons.push('Live tied game');
            } else if (diff === 1) {
              score += 30;
              reasons.push('Live 1-goal/run game');
            } else if (diff >= 4) {
              score -= 20; // Live blowout
            }
          } else { // Football, Basketball
            if (diff <= 3) {
              score += 35;
              reasons.push(`Live tight game (${diff} pt diff)`);
            } else if (diff <= 7) {
              score += 25;
              reasons.push(`Live close game (${diff} pt diff)`);
            } else if (diff >= 20) {
              score -= 20; // Live blowout
            }
          }
        } else if (isCompleted) {
          // COMPLETED GAME LOGIC
          if (isLowScoreSport) {
            if (diff === 0) {
              score += 35;
              reasons.push('Tied game');
            } else if (diff === 1) {
              score += 30;
              reasons.push('1-goal/run game');
            } else if (diff >= 5) {
              score -= 20;
            }
          } else {
            if (diff <= 3) {
              score += 35;
              reasons.push(`Tight final (${diff} pt diff)`);
            } else if (diff <= 7) {
              score += 25;
              reasons.push(`Close final (${diff} pt diff)`);
            } else if (diff >= 22) {
              score -= 20;
            }
          }
        }
      }
    }
  }

  // Live state bonus
  if (isLive) {
    score += 12;
  }

  const isTopMatchup = score >= 55 || reasons.some(r => 
    r.includes('Ultra-tight') || 
    r.includes('Tight spread') || 
    r.includes('Tight moneyline') || 
    r.includes('Close moneyline') || 
    r.includes('Ranked') || 
    r.includes('Live 1-goal') || 
    r.includes('Live tight') || 
    r.includes('Live tied') ||
    r.includes('1-goal') ||
    r.includes('Tight final')
  );

  return {
    score,
    isTopMatchup,
    reason: reasons.join(' · ') || 'Popular matchup'
  };
}

function renderLeagueGroups(container, leagueResults, renderGame, emptyLabel) {
  if (leagueResults.every((r) => r.events === null)) {
    container.innerHTML = '<p class="error">Couldn\'t load sports data right now. Try refreshing the page.</p>';
    return;
  }

  const byGroup = groupBy(leagueResults, (r) => r.league.group);
  container.innerHTML = '';
  for (const [groupName, leagues] of byGroup) {
    const hasGames = leagues.some((r) => r.events && r.events.length > 0);
    const groupEl = document.createElement('details');
    groupEl.className = 'league-group';
    if (hasGames) groupEl.open = true;
    let groupHtml = `<summary><h3>${groupName}</h3></summary><div class="league-group-body"><ul class="game-list">`;
    for (const { league, events } of leagues) {
      if (events === null) {
        groupHtml += `<li class="game-row muted-row is-standard-matchup"><div class="game-top-meta"><span class="team-name">${league.name}</span><span class="game-status">&ndash; Couldn't load</span></div></li>`;
      } else if (events.length === 0) {
        groupHtml += `<li class="game-row muted-row is-standard-matchup"><div class="game-top-meta"><span class="team-name">${league.name}</span><span class="game-status">&ndash; ${emptyLabel}</span></div></li>`;
      } else {
        groupHtml += events.map((ev) => renderGame(ev, league)).join('');
      }
    }
    groupHtml += `</ul></div>`;
    groupEl.innerHTML = groupHtml;
    container.appendChild(groupEl);
  }
  updateMustWatchGroupVisibility();
}

function nameHtml(participant) {
  const rankPrefix = participant?.rank ? `<span class="team-rank">#${participant.rank}</span>` : '';
  const nameStr = participant.link
    ? `<a href="${participant.link}" target="_blank" rel="noopener noreferrer">${participant.name}</a>`
    : participant.name;
  return `${rankPrefix}${nameStr}`;
}

function renderOddsBar(ev) {
  const o = ev.odds;
  if (!o) return '';

  const awayShort = ev.away?.shortName || ev.away?.name || 'Away';
  const homeShort = ev.home?.shortName || ev.home?.name || 'Home';

  let html = `<div class="game-odds-container">`;

  if (ev.state === 'in') {
    const isOff = o.liveHomeML === 'OFF' || o.liveAwayML === 'OFF';
    const hasLiveML = o.liveHomeML && o.liveAwayML && !isOff;

    html += `<div class="odds-bar live-odds-bar">`;
    html += `<span class="odds-badge live-badge">● LIVE ODDS</span>`;

    if (hasLiveML) {
      const awayML = formatML(o.liveAwayML);
      const homeML = formatML(o.liveHomeML);
      const drawML = o.liveDrawML ? ` · Draw ${formatML(o.liveDrawML)}` : '';
      html += `<span class="odds-chip live-ml-chip">Live ML: <b>${awayShort} ${awayML}</b> / <b>${homeShort} ${homeML}</b>${drawML}</span>`;
    } else if (isOff) {
      html += `<span class="odds-chip muted-chip">Live Odds: Board Locked</span>`;
    }

    if (o.winProb !== null && o.winProb !== undefined) {
      html += `<span class="odds-chip win-prob-chip">Win Prob: <b>${homeShort} ${o.winProb}%</b></span>`;
    }

    const openMLStr = (o.openAwayML && o.openHomeML) 
      ? `Open ML: ${awayShort} ${formatML(o.openAwayML)} / ${homeShort} ${formatML(o.openHomeML)}`
      : ((o.closeAwayML && o.closeHomeML) ? `Line ML: ${awayShort} ${formatML(o.closeAwayML)} / ${homeShort} ${formatML(o.closeHomeML)}` : '');
    const lineStr = o.details ? `Line: ${o.details}` : '';
    const ouStr = o.overUnder ? `${o.overUnder}` : '';
    const preParts = [lineStr, openMLStr, ouStr].filter(Boolean).join(' · ');

    if (preParts) {
      html += `<span class="odds-chip pre-compare-chip">Pre-Game: ${preParts}</span>`;
    }

    html += `</div>`;
  } else {
    const isPost = ev.state === 'post';
    html += `<div class="odds-bar ${isPost ? 'post-odds-bar' : 'pre-odds-bar'}">`;
    
    if (isPost) {
      html += `<span class="odds-badge post-badge">Pregame Line</span>`;
    } else if (o.providerName) {
      const providerContent = o.providerLink
        ? `<a href="${o.providerLink}" target="_blank" rel="noopener noreferrer" class="odds-provider-link">${o.providerName} ↗</a>`
        : o.providerName;
      html += `<span class="odds-badge provider-badge">${providerContent}</span>`;
    }

    if (o.details) {
      html += `<span class="odds-chip highlight-chip">Line: <b>${o.details}</b></span>`;
    }

    if (o.closeAwayML && o.closeHomeML) {
      const awayMLVal = formatML(o.closeAwayML);
      const homeMLVal = formatML(o.closeHomeML);
      const drawMLVal = o.closeDrawML ? ` / Draw ${formatML(o.closeDrawML)}` : '';
      html += `<span class="odds-chip ml-chip">ML: <b>${awayShort} ${awayMLVal}</b> / <b>${homeShort} ${homeMLVal}</b>${drawMLVal}</span>`;
    }

    if (o.awaySpread && o.homeSpread) {
      html += `<span class="odds-chip spread-chip">Spread: <b>${o.awaySpread}</b> / <b>${o.homeSpread}</b></span>`;
    }

    if (o.overUnder) {
      html += `<span class="odds-chip ou-chip"><b>${o.overUnder}</b></span>`;
    }

    html += `</div>`;
  }

  html += `</div>`;
  return html;
}

function renderYesterdayGame(ev, league) {
  if (!ev.completed) return '';
  const away = ev.away, home = ev.home;
  const excitement = calculateExcitement(ev, league);
  const topBadge = excitement.isTopMatchup 
    ? `<span class="top-matchup-badge" title="${escapeAttr(excitement.reason)}">🔥 Top Matchup</span>` 
    : '';
  const modelName = getAiModelName();
  const sportsPrompt = buildSportsPrompt(ev, league);

  return `<li class="game-row ${excitement.isTopMatchup ? 'is-top-matchup' : 'is-standard-matchup'}" data-top-matchup="${excitement.isTopMatchup}">
    <div class="game-top-meta">
      <span class="game-league-name">${league.name}</span>
      <div class="game-status-wrapper">
        ${topBadge}
        <span class="game-status">${ev.statusDetail || 'Final'}</span>
        <button class="ask-gemini-btn sports-ask-ai-btn" data-prompt="${escapeAttr(sportsPrompt)}" title="Ask ${modelName} about this matchup">
          <span class="sparkle-icon">✨</span> Ask ${modelName}
        </button>
      </div>
    </div>
    <div class="game-teams-grid">
      <div class="team-row">
        <span class="team-name">${nameHtml(away)}</span>
        <span class="team-score">${away.score}</span>
      </div>
      <div class="team-row">
        <span class="team-name">${nameHtml(home)}</span>
        <span class="team-score">${home.score}</span>
      </div>
    </div>
    ${renderOddsBar(ev)}
  </li>`;
}

function renderScheduledGame(ev, league) {
  const away = ev.away, home = ev.home;
  const time = new Date(ev.date).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
  let statusHtml;
  if (ev.state === 'in') {
    statusHtml = `<span class="game-status live">${ev.statusDetail || 'Live'}</span>`;
  } else if (ev.state === 'post') {
    statusHtml = `<span class="game-status">${ev.statusDetail || 'Final'}</span>`;
  } else {
    statusHtml = `<span class="game-status">${time}</span>`;
  }
  const showScores = ev.state !== 'pre';
  const excitement = calculateExcitement(ev, league);
  const topBadge = excitement.isTopMatchup 
    ? `<span class="top-matchup-badge" title="${escapeAttr(excitement.reason)}">🔥 Top Matchup</span>` 
    : '';
  const modelName = getAiModelName();
  const sportsPrompt = buildSportsPrompt(ev, league);

  return `<li class="game-row ${excitement.isTopMatchup ? 'is-top-matchup' : 'is-standard-matchup'}" data-top-matchup="${excitement.isTopMatchup}">
    <div class="game-top-meta">
      <span class="game-league-name">${league.name}</span>
      <div class="game-status-wrapper">
        ${topBadge}
        ${statusHtml}
        <button class="ask-gemini-btn sports-ask-ai-btn" data-prompt="${escapeAttr(sportsPrompt)}" title="Ask ${modelName} about this matchup">
          <span class="sparkle-icon">✨</span> Ask ${modelName}
        </button>
      </div>
    </div>
    <div class="game-teams-grid">
      <div class="team-row">
        <span class="team-name">${nameHtml(away)}</span>
        ${showScores ? `<span class="team-score">${away.score}</span>` : ''}
      </div>
      <div class="team-row">
        <span class="team-name">${nameHtml(home)}</span>
        ${showScores ? `<span class="team-score">${home.score}</span>` : ''}
      </div>
    </div>
    ${renderOddsBar(ev)}
  </li>`;
}

