// ---------- Golf Leaderboards ----------

const GOLF_TOURS = [
  { id: 'pga', name: 'PGA TOUR', path: 'golf/pga', siteSport: 'golf' },
  { id: 'lpga', name: 'LPGA Tour', path: 'golf/lpga', siteSport: 'golf' },
  { id: 'liv', name: 'LIV Golf', path: 'golf/liv', siteSport: 'golf' },
];

function formatGolfDates(startStr, endStr) {
  try {
    const s = new Date(startStr);
    const e = endStr ? new Date(endStr) : s;
    const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const startMonth = MONTHS[s.getUTCMonth()];
    const endMonth = MONTHS[e.getUTCMonth()];
    const startDay = s.getUTCDate();
    const endDay = e.getUTCDate();
    const year = e.getUTCFullYear();
    if (startMonth === endMonth) {
      return `${startMonth} ${startDay} – ${endDay}, ${year}`;
    }
    return `${startMonth} ${startDay} – ${endMonth} ${endDay}, ${year}`;
  } catch {
    return '';
  }
}

let loggedGolfSample = false;

function getGolfThruValue(player, isEventCompleted = false) {
  if (!player) return '-';

  // Check explicit status string for CUT / WD / OFFICIAL
  const statusStr = typeof player.status === 'string'
    ? player.status
    : (player.status?.type?.name || player.status?.name || player.status?.type?.shortDetail || '');

  if (statusStr.includes('CUT') || player.status === 'CUT') return 'CUT';
  if (statusStr.includes('WD') || player.status === 'WD') return 'WD';
  if (isEventCompleted || player.status?.type?.completed === true || statusStr.includes('OFFICIAL') || statusStr.includes('FINAL')) {
    return 'F';
  }

  // Find hole-by-hole breakdown array from ESPN linescores payload
  const activeRound = Array.isArray(player.linescores)
    ? (player.linescores.slice().reverse().find(r => Array.isArray(r.linescores) && r.linescores.length > 0) || player.linescores[0])
    : null;

  const holeList = activeRound?.linescores;

  if (Array.isArray(holeList)) {
    const holesCompleted = holeList.length;
    if (holesCompleted === 0) {
      // Not teed off yet
      const teeTime = player.teeTime ?? player.status?.teeTime;
      if (teeTime) {
        try {
          const d = new Date(teeTime);
          if (!isNaN(d.getTime())) {
            return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
          }
        } catch {}
        if (typeof teeTime === 'string' && teeTime.trim()) return teeTime.trim();
      }
      return '-';
    }
    if (holesCompleted === 18) {
      return 'F';
    }
    if (holesCompleted >= 1 && holesCompleted <= 17) {
      return `Thru ${holesCompleted}`;
    }
  }

  // Fallback checks if linescores hole array is absent
  const firstLs = player.linescores?.[0];
  if (firstLs) {
    if (firstLs.value === 18 || firstLs.thru === 18) return 'F';
    if (typeof firstLs.thru === 'number' && firstLs.thru > 0 && firstLs.thru < 18) {
      return `Thru ${firstLs.thru}`;
    }
    if (typeof firstLs.holesPlayed === 'number' && firstLs.holesPlayed > 0 && firstLs.holesPlayed < 18) {
      return `Thru ${firstLs.holesPlayed}`;
    }
  }

  return '-';
}

async function loadGolfLeaderboards() {
  const container = document.getElementById('golf-list');
  if (!container) return;

  const results = await Promise.all(GOLF_TOURS.map(async (tour) => {
    const url = `https://site.api.espn.com/apis/site/v2/sports/${tour.path}/scoreboard`;
    try {
      const data = await fetchWithFallback(url);
      return { tour, data };
    } catch (err) {
      console.warn(`Golf fetch failed for ${tour.name}:`, err);
      return { tour, data: null };
    }
  }));

  if (results.every((r) => r.data === null)) {
    container.innerHTML = '<p class="error">Couldn\'t load golf data right now. Try refreshing the page.</p>';
    return;
  }

  container.innerHTML = '';

  for (const { tour, data } of results) {
    const groupEl = document.createElement('details');
    groupEl.className = 'league-group golf-card';

    const events = data?.events || [];
    if (events.length > 0) groupEl.open = true;

    if (!data || events.length === 0) {
      groupEl.innerHTML = `
        <summary><div class="golf-summary-header"><h3>${tour.name}</h3><span class="game-status">Scheduled</span></div></summary>
        <div class="league-group-body">
          <p class="empty">No tournament scheduled this week.</p>
        </div>`;
      container.appendChild(groupEl);
      continue;
    }

    const event = events[0];
    const comp = event.competitions?.[0] || {};
    const statusType = comp.status?.type || event.status?.type || {};
    const isLive = statusType.state === 'in';
    const isCompleted = statusType.state === 'post' || statusType.completed;

    let statusText = '';
    let statusBadgeClass = 'game-status';
    if (isLive) {
      statusBadgeClass = 'game-status live';
      statusText = '● LIVE · ' + (statusType.detail || statusType.shortDetail || 'In Progress');
    } else if (isCompleted) {
      statusText = 'Final · ' + (statusType.detail || statusType.shortDetail || 'Complete');
    } else {
      if (event.date) {
        const startDate = new Date(event.date);
        const dateFormatted = startDate.toLocaleDateString('en-US', {
          timeZone: 'UTC',
          weekday: 'short',
          month: 'short',
          day: 'numeric'
        });
        statusText = `Scheduled · Starts ${dateFormatted}`;
      } else {
        statusText = 'Scheduled';
      }
    }

    const venue = comp.venue ? `${comp.venue.fullName || ''}${comp.venue.address?.city ? ' · ' + comp.venue.address.city : ''}` : '';
    const dateRange = event.date ? formatGolfDates(event.date, event.endDate) : '';

    const competitors = comp.competitors || [];
    const showLimit = 8;
    const tournamentId = `${tour.id}-leaderboard`;

    let html = `
      <summary>
        <div class="golf-summary-header">
          <h3>${tour.name}</h3>
          <span class="${statusBadgeClass}">${statusText}</span>
        </div>
      </summary>
      <div class="league-group-body golf-body">
        <div class="golf-tourney-meta">
          <div class="golf-tourney-title">${event.name}</div>
          <div class="golf-tourney-sub">${dateRange}${venue ? ' · ' + venue : ''}</div>
        </div>`;

    if (competitors.length === 0) {
      html += `<p class="empty" style="margin-top:0.75rem;">Field and tee times will be available closer to the tournament start.</p>`;
    } else {
      html += `
        <div class="golf-table-wrap">
          <table class="golf-table" id="${tournamentId}">
            <thead>
              <tr>
                <th class="col-pos">Pos</th>
                <th class="col-player">Player</th>
                <th class="col-score">Score</th>
                <th class="col-thru">Thru</th>
              </tr>
            </thead>
            <tbody>`;

      competitors.forEach((c, idx) => {
        if (!loggedGolfSample) {
          console.log('Golfer payload:', c);
          loggedGolfSample = true;
        }
        const isHidden = idx >= showLimit;
        const pos = c.status?.position?.displayName || c.order || (idx + 1);
        const athlete = c.athlete || {};
        const name = athlete.displayName || athlete.fullName || 'Golfer';
        const athleteId = athlete.id || c.id;
        const link = athleteId
          ? `https://www.espn.com/golf/player/_/id/${athleteId}`
          : null;

        const playerHtml = link
          ? `<a href="${link}" target="_blank" rel="noopener noreferrer">${name}</a>`
          : name;

        const flagImg = athlete.flag?.href
          ? `<img class="golf-flag" src="${athlete.flag.href}" alt="${athlete.flag.alt || ''}" title="${athlete.flag.alt || ''}">`
          : '';

        const score = c.score || 'E';
        const scoreClass = score.startsWith('-') ? 'score-under' : (score.startsWith('+') ? 'score-over' : 'score-even');

        const thruValue = getGolfThruValue(c, isCompleted);

        html += `
          <tr class="golf-row ${isHidden ? 'golf-row-extra hidden' : ''}">
            <td class="col-pos">${pos}</td>
            <td class="col-player">${flagImg}${playerHtml}</td>
            <td class="col-score ${scoreClass}">${score}</td>
            <td class="col-thru">${thruValue}</td>
          </tr>`;
      });

      html += `</tbody></table></div>`;

      if (competitors.length > showLimit) {
        html += `
          <button type="button" class="golf-expand-btn" data-target="${tournamentId}">
            Show full field (${competitors.length} golfers)
          </button>`;
      }
    }

    html += `</div>`;
    groupEl.innerHTML = html;
    container.appendChild(groupEl);
  }

  container.querySelectorAll('.golf-expand-btn').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const targetId = e.currentTarget.getAttribute('data-target');
      const table = document.getElementById(targetId);
      if (!table) return;
      const hiddenRows = table.querySelectorAll('.golf-row-extra');
      const isExpanded = btn.classList.contains('expanded');

      hiddenRows.forEach((row) => {
        if (isExpanded) {
          row.classList.add('hidden');
        } else {
          row.classList.remove('hidden');
        }
      });

      if (isExpanded) {
        btn.classList.remove('expanded');
        const totalRows = table.querySelectorAll('tbody tr').length;
        btn.textContent = `Show full field (${totalRows} golfers)`;
      } else {
        btn.classList.add('expanded');
        btn.textContent = 'Show top 8 only';
      }
    });
  });
}

// ---------- Ask AI Handlers (Copy Prompt + Toast + Open Gemini/ChatGPT) ----------

function buildSportsPrompt(ev, league) {
  const sportName = league?.name || 'Sports';
  const awayName = ev?.away?.name || 'Away Team';
  const homeName = ev?.home?.name || 'Home Team';

  // Game Time or Status
  let timeOrStatus = '';
  if (ev?.state === 'in') {
    const aScore = ev?.away?.score !== undefined ? ev.away.score : '';
    const hScore = ev?.home?.score !== undefined ? ev.home.score : '';
    const scoreStr = (aScore !== '' && hScore !== '') ? ` ${aScore}-${hScore}` : '';
    timeOrStatus = `(Live${scoreStr}, ${ev.statusDetail || 'In Progress'})`;
  } else if (ev?.completed || ev?.state === 'post') {
    const aScore = ev?.away?.score !== undefined ? ev.away.score : '';
    const hScore = ev?.home?.score !== undefined ? ev.home.score : '';
    const scoreStr = (aScore !== '' && hScore !== '') ? ` ${aScore}-${hScore}` : '';
    timeOrStatus = `(Final${scoreStr})`;
  } else if (ev?.date) {
    const timeStr = new Date(ev.date).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
    timeOrStatus = `at ${timeStr}`;
  }

  // Odds Construction
  const odds = ev?.odds;
  const oddsParts = [];

  if (odds) {
    // 1. Moneyline
    let mlStr = '';
    const { homeML, awayML } = extractMoneylineValues(odds);
    if (homeML !== null && awayML !== null) {
      const hStr = homeML > 0 ? `+${homeML}` : `${homeML}`;
      const aStr = awayML > 0 ? `+${awayML}` : `${awayML}`;
      mlStr = `Odds: ${awayName} ${aStr} / ${homeName} ${hStr}`;
    } else if (odds.details) {
      mlStr = `Odds: ${odds.details}`;
    }

    if (mlStr) oddsParts.push(mlStr);

    // 2. Spread
    if (odds.awaySpread && odds.homeSpread) {
      oddsParts.push(`Spread: ${odds.awaySpread} / ${odds.homeSpread}`);
    } else if (odds.details && !mlStr.includes(odds.details)) {
      oddsParts.push(`Line: ${odds.details}`);
    }

    // 3. Over/Under
    if (odds.overUnder) {
      const ouVal = String(odds.overUnder).trim();
      const ouFormatted = /^o\/?u/i.test(ouVal) ? ouVal : `O/U: ${ouVal}`;
      oddsParts.push(ouFormatted);
    }
  }

  const oddsText = oddsParts.length > 0 ? ` ${oddsParts.join(', ')}.` : '';

  return `Give me a concise breakdown and key story lines for this matchup: ${sportName} · ${awayName} vs ${homeName} ${timeOrStatus}.${oddsText} Why is this line set where it is, and what are the main factors to watch?`;
}

const AI_MODEL_PREF_KEY = 'user_ai_model_pref';

function getAiModelPref() {
  const saved = localStorage.getItem(AI_MODEL_PREF_KEY);
  return (saved === 'chatgpt') ? 'chatgpt' : 'gemini';
}

function getAiModelName() {
  return getAiModelPref() === 'chatgpt' ? 'ChatGPT' : 'Gemini';
}

function updateHeadlineButtonLabels() {
  const modelName = getAiModelName();
  const buttons = document.querySelectorAll('.ask-gemini-btn');
  buttons.forEach(btn => {
    btn.title = btn.hasAttribute('data-prompt')
      ? `Ask ${modelName} about this matchup`
      : `Ask ${modelName} about this headline`;
    btn.innerHTML = `<span class="sparkle-icon">✨</span> Ask ${modelName}`;
  });
}

function initAiModelSelect() {
  const selectEl = document.getElementById('ai-model-select');
  if (!selectEl) return;

  const currentPref = getAiModelPref();
  selectEl.value = currentPref;

  selectEl.addEventListener('change', (e) => {
    const val = e.target.value;
    localStorage.setItem(AI_MODEL_PREF_KEY, val);
    updateHeadlineButtonLabels();
  });
}

let toastTimeout = null;
function showToast(msg = 'Headline copied!') {
  const toast = document.getElementById('toast');
  const msgEl = document.getElementById('toast-message');
  if (!toast) return;

  if (msgEl) msgEl.textContent = msg;

  if (toastTimeout) clearTimeout(toastTimeout);

  toast.classList.remove('hidden', 'toast-hiding');

  toastTimeout = setTimeout(() => {
    toast.classList.add('toast-hiding');
    setTimeout(() => {
      toast.classList.add('hidden');
      toast.classList.remove('toast-hiding');
    }, 300);
  }, 3000);
}

function fallbackCopyText(text) {
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.style.position = 'fixed';
  textarea.style.opacity = '0';
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();
  try {
    document.execCommand('copy');
  } catch (e) {
    console.error('Fallback copy failed', e);
  }
  document.body.removeChild(textarea);
}

function handleAskAiClick(input, isPrompt = false) {
  if (!input) return;
  const model = getAiModelPref();
  const promptText = isPrompt
    ? input
    : `Please summarize and provide context for this headline: "${input}"`;

  // 1. Copy Prompt to Clipboard
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(promptText).catch(() => {
      fallbackCopyText(promptText);
    });
  } else {
    fallbackCopyText(promptText);
  }

  // 2. Show Toast Feedback
  if (model === 'chatgpt') {
    showToast('Copied! Paste into ChatGPT.');
  } else {
    showToast("Copied! Tap 'Open in App' at the top of Safari if it opens in browser.");
  }

  // 3. Open corresponding app scheme / URL in new window/tab after 500ms delay
  setTimeout(() => {
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    if (model === 'chatgpt') {
      if (isMobile) {
        window.location.href = 'chatgpt://';
        setTimeout(() => {
          window.open('https://chatgpt.com', '_blank', 'noopener,noreferrer');
        }, 800);
      } else {
        window.open('https://chatgpt.com', '_blank', 'noopener,noreferrer');
      }
    } else {
      // Gemini
      if (isMobile) {
        window.location.href = 'googleapp://';
        setTimeout(() => {
          window.open('https://gemini.google.com', '_blank', 'noopener,noreferrer');
        }, 800);
      } else {
        window.open('https://gemini.google.com', '_blank', 'noopener,noreferrer');
      }
    }
  }, 500);
}

function initAskGeminiHandlers() {
  document.body.addEventListener('click', (e) => {
    const btn = e.target.closest('.ask-gemini-btn');
    if (btn) {
      e.preventDefault();
      e.stopPropagation();
      const promptAttr = btn.getAttribute('data-prompt');
      const titleAttr = btn.getAttribute('data-title');

      if (promptAttr) {
        handleAskAiClick(promptAttr, true);
      } else if (titleAttr) {
        handleAskAiClick(titleAttr, false);
      }
    }
  });
}

// ---------- Must-Watch Filter Toggle ----------

const MUST_WATCH_PREF_KEY = 'user_must_watch_pref';

function getMustWatchPref() {
  return localStorage.getItem(MUST_WATCH_PREF_KEY) === 'true';
}

function setMustWatchPref(active) {
  localStorage.setItem(MUST_WATCH_PREF_KEY, active ? 'true' : 'false');
  applyMustWatchState(active);
}

function applyMustWatchState(active) {
  if (active) {
    document.body.classList.add('must-watch-active');
  } else {
    document.body.classList.remove('must-watch-active');
  }

  const checkbox = document.getElementById('toggle-must-watch');
  if (checkbox) checkbox.checked = active;

  const btn = document.getElementById('must-watch-btn');
  if (btn) {
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    if (active) btn.classList.add('active');
    else btn.classList.remove('active');
  }

  updateMustWatchGroupVisibility();
}

function updateMustWatchGroupVisibility() {
  const isMustWatchActive = document.body.classList.contains('must-watch-active');
  const leagueGroups = document.querySelectorAll('.league-group');

  leagueGroups.forEach(group => {
    if (!isMustWatchActive) {
      group.classList.remove('group-filtered-out');
      return;
    }
    const topGames = group.querySelectorAll('.game-row.is-top-matchup');
    if (topGames.length === 0) {
      group.classList.add('group-filtered-out');
    } else {
      group.classList.remove('group-filtered-out');
    }
  });
}

function initMustWatchToggle() {
  const currentPref = getMustWatchPref();
  applyMustWatchState(currentPref);

  const checkbox = document.getElementById('toggle-must-watch');
  if (checkbox) {
    checkbox.addEventListener('change', (e) => {
      setMustWatchPref(e.target.checked);
    });
  }

  const btn = document.getElementById('must-watch-btn');
  if (btn) {
    btn.addEventListener('click', () => {
      const active = document.body.classList.contains('must-watch-active');
      setMustWatchPref(!active);
    });
  }
}

// ---------- Init ----------

function initOddsToggle() {
  const toggleBtn = document.getElementById('toggle-odds');
  if (!toggleBtn) return;

  const savedSetting = localStorage.getItem('showOdds');
  if (savedSetting === 'false') {
    toggleBtn.checked = false;
    document.body.classList.add('hide-odds');
  } else {
    toggleBtn.checked = true;
    document.body.classList.remove('hide-odds');
  }

  toggleBtn.addEventListener('change', (e) => {
    if (e.target.checked) {
      document.body.classList.remove('hide-odds');
      localStorage.setItem('showOdds', 'true');
    } else {
      document.body.classList.add('hide-odds');
      localStorage.setItem('showOdds', 'false');
    }
  });
}

function setLastUpdated() {
  document.getElementById('last-updated').textContent =
    `Last checked ${today.toLocaleString(undefined, { hour: 'numeric', minute: '2-digit', month: 'short', day: 'numeric' })}`;
}

initOddsToggle();
initMustWatchToggle();
initAiModelSelect();
initAskGeminiHandlers();
setLastUpdated();
loadHeadlines();
loadGolfLeaderboards();
loadYesterdayScores();
loadTodayGames();
loadTomorrowGames();

